17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * SHA-256 reduced to a lower-case hex string. Kept separate from the owner controller and the
25	 * {@code Owner} model so the single way this codebase turns a value into a stable hex digest lives in
26	 * one place, as a pure function with no web or persistence dependencies. Several owner values are
27	 * derived from such a digest and share this helper: the {@link CustomerCode} hash component and the
28	 * {@link HouseholdNormalizer} household id each keep a leading slice of it.
29	 */
30	public abstract class Sha256 {
31	
32	    /**
33	     * The lower-case hex SHA-256 of the UTF-8 bytes of {@code value}: 64 hex characters, two per
34	     * digest byte. SHA-256 is a standard algorithm required to be present on every JVM, so its
35	     * absence is treated as a fatal misconfiguration rather than a recoverable error.
36	     *
37	     * @param value the value to digest (non-null)
38	     * @return the 64-character lower-case hex digest
39	     */
40	    public static String hex(String value) {
41	        try {
42	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
43	            StringBuilder hex = new StringBuilder(digest.length * 2);
44	            for (byte b : digest) {
45	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
46	                hex.append(Character.forDigit(b & 0xF, 16));
47	            }
48	            return hex.toString();
49	        }
50	        catch (NoSuchAlgorithmException ex) {
51	            // SHA-256 is a standard algorithm required to be present on every JVM.
52	            throw new IllegalStateException("SHA-256 not available", ex);
53	        }
54	    }
55	
56	}
