247	    /**
248	     * Build a customer code formatted '<REGION>-<HASH8>', where REGION is the region derived from the
249	     * owner's postcode (see {@link LocalityResolver#resolveFromPostcode}) and HASH8 is the first eight
250	     * upper-case hex characters of the SHA-256 digest of the owner's normalized telephone concatenated
251	     * with the last name (e.g. 'NSW-1A2B3C4D'). The base code carries no sequence number, so two
252	     * distinct owners whose '(telephone, lastName)' pairs hash alike would otherwise share a code; when
253	     * the computed code collides with an existing owner's customer code, '-<n>' is appended with the
254	     * smallest n of 2 or more that makes it unique (see {@link #deduplicateCustomerCode}).
255	     */
256	    private String generateCustomerCode(Owner owner) {
257	        String region = LocalityResolver.resolveFromPostcode(owner.getPostcode());
258	        String code = CustomerCode.of(region, owner.getTelephone(), owner.getLastName());
259	        return deduplicateCustomerCode(code);
260	    }
