262	    /**
263	     * Returns {@code code} unchanged when no existing owner already carries it, otherwise the code with
264	     * '-<n>' appended, choosing the smallest n of 2 or more that makes the result unique among existing
265	     * owners' customer codes.
266	     */
267	    private String deduplicateCustomerCode(String code) {
268	        Set<String> existing = ownerRepository.findAll().stream()
269	            .map(Owner::getCustomerCode)
270	            .filter(Objects::nonNull)
271	            .collect(Collectors.toSet());
272	        if (!existing.contains(code)) {
273	            return code;
274	        }
275	        for (int n = 2; ; n++) {
276	            String candidate = code + "-" + n;
277	            if (!existing.contains(candidate)) {
278	                return candidate;
279	            }
280	        }
281	    }
