19	/**
20	 * Computation of the Luhn check digit over the digits contained in a string. Kept separate from the
21	 * owner controller and the {@code Owner} model so the rule lives in one place, as a pure function
22	 * with no web or persistence dependencies. Mirrors {@link LocalityResolver}, which does the same for
23	 * localities.
24	 *
25	 * <p>The standard Luhn algorithm is applied to the decimal digits found in the input (any non-digit
26	 * character is ignored): reading right to left, every second digit is doubled (subtracting 9 when the
27	 * doubled value exceeds 9) and all resulting values are summed. The check digit is the amount that
28	 * must be added to that sum to reach the next multiple of ten, i.e. {@code (10 - (sum % 10)) % 10},
29	 * a single digit in the range 0-9.
30	 */
31	public abstract class LuhnCheckDigit {
32	
33	    /**
34	     * Compute the Luhn check digit over the decimal digits contained in {@code value}.
35	     *
36	     * @param value the string whose digits are checked (a {@code null} value is treated as containing
37	     *              no digits, yielding {@code 0})
38	     * @return the Luhn check digit, a single digit in the range 0-9
39	     */
40	    public static int of(String value) {
41	        if (value == null) {
42	            return 0;
43	        }
44	        int sum = 0;
45	        boolean doubleDigit = true;
