338	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
339	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
340	        OwnerCreatedEvent event = new OwnerCreatedEvent(EVENT_SEQ.incrementAndGet(),
