382	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
383	     */
384	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
385	        List<String> missing = new ArrayList<>();
386	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
387	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
388	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
389	            missing.add("address");
390	        }
391	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
392	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
