426	    /**
427	     * Normalizes the submitted address on create to its canonical form (see
428	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
429	     * stored and returned, and the form every later address comparison (the required-field check,
430	     * household duplicate detection and the shared household id) is judged on. The structured fields
431	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
432	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
433	     * derived from them when a structured {@code addressLine1} is present, falling back to the
434	     * normalized flat {@code address} otherwise. Any absent field is left absent so
435	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
436	     * after normalization likewise reduces to the empty string and is rejected there.
437	     *
438	     * @param ownerFieldsDto the submitted owner fields
439	     */
440	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
441	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
442	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
443	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
444	        ownerFieldsDto.setAddressLine1(addressLine1);
445	        ownerFieldsDto.setAddressLine2(addressLine2);
446	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
447	    }
448	
449	    /**
450	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
451	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
452	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
453	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
454	     * is the single value every later reader of the address (the required-field check, household
455	     * duplicate detection and the shared household id) is judged on.
456	     *
457	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
458	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
459	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
460	     * @return the composed flat address, or {@code null} when no address form was supplied
461	     */
462	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
463	        if (isBlank(addressLine1)) {
464	            return flatAddress;
465	        }
466	        if (isBlank(addressLine2)) {
467	            return addressLine1;
468	        }
469	        return addressLine1 + " " + addressLine2;
470	    }
