473	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
474	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
475	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
476	     * {@code 400 Bad Request}.
477	     *
478	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
479	     *                       {@link #rejectBlankOwnerFields} having already run)
480	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
481	     */
482	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
483	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
484	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
