488	    /**
489	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
490	     * untouched (email is optional). When present it is reduced to its canonical form (see
491	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
492	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
493	     *
494	     * @param ownerFieldsDto the submitted owner fields
495	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
496	     *                                     or its domain is on the disposable-domain blocklist
497	     */
498	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
499	        String email = ownerFieldsDto.getEmail();
500	        if (email == null || email.isBlank()) {
501	            return;
502	        }
503	        String normalized = EmailNormalizer.normalize(email)
504	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
505	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
506	            throw new InvalidOwnerFieldsException(List.of("email"));
507	        }
