511	    /**
512	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
513	     * duplicate detection is now expressed through the single derived {@code identityKey}
514	     * ({@code sha256hex(normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))}, see
515	     * {@link OwnerIdentity}), which replaces the previously separate telephone, email and household
516	     * checks. Two owners denote the same person when their whole identity keys are equal, so a create
517	     * is rejected as a {@code 409 Conflict} when another (non-deleted) owner already carries the same
518	     * key. Because the telephone is part of the key, two owners who share a last name and postcode but
519	     * carry different telephones have different keys and are both allowed (they are instead recorded as
520	     * a {@linkplain #findPossibleDuplicate possible duplicate}); an email or a household on its own no
521	     * longer makes a duplicate.
522	     *
523	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
524	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
525	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
526	     */
527	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
528	        String identityKey = OwnerIdentity.identityKey(
529	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
530	        boolean inUse = activeOwners().stream()
531	            .map(OwnerIdentity::identityKey)
532	            .anyMatch(identityKey::equals);
533	        if (inUse) {
534	            throw new DuplicateOwnerIdentityException(identityKey);
535	        }
536	    }
