539	     * The owners considered by duplicate detection: every persisted owner except those flagged
540	     * {@code deleted}. A soft-deleted owner is retained but must never make a later create look like a
541	     * duplicate, so both the hard-duplicate identity check ({@link #rejectDuplicateIdentity}) and the
542	     * soft {@linkplain #findPossibleDuplicate possible-duplicate} match are judged against these owners
543	     * alone. Only owners already persisted (before this create) are included.
544	     *
545	     * @return the non-deleted owners currently persisted
546	     */
547	    private List<Owner> activeOwners() {
548	        return this.clinicService.findAllOwners().stream()
549	            .filter(owner -> !owner.isDeleted())
550	            .toList();
