584	    /**
585	     * Returns the existing owners (before this create) belonging to the given household, i.e. those
586	     * whose stored {@code householdId} equals the value derived for the owner being created. As with
587	     * {@link #countHouseholdMembers}, only owners already persisted are included, so the owner being
588	     * created is never among them.
589	     *
590	     * @param householdId the household identifier derived for the owner being created (see
591	     *                    {@link HouseholdNormalizer#toHouseholdId})
592	     * @return the existing owners already sharing that household (empty when {@code householdId} is
593	     *         {@code null})
594	     */
595	    private List<Owner> householdMembers(String householdId) {
596	        if (householdId == null) {
597	            return List.of();
598	        }
599	        return this.clinicService.findAllOwners().stream()
600	            .filter(member -> householdId.equals(member.getHouseholdId()))
601	            .toList();
