604	    /**
605	     * Caps a new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
606	     * {@code membershipLevel} among their existing household members. The owner's own level is the
607	     * value {@linkplain OwnerMapper#membershipLevel(Owner) it would otherwise report}; it is capped at
608	     * {@code maxHouseholdLevel + 1}. When the household has no existing member no cap applies and the
609	     * owner's own level is returned unchanged.
610	     *
611	     * @param owner the owner being created, already stamped with its household id and size
612	     * @return the (possibly capped) membership level to stamp on the owner
613	     */
614	    private int cappedMembershipLevel(Owner owner) {
615	        int ownLevel = this.ownerMapper.membershipLevel(owner);
616	        OptionalInt maxHouseholdLevel = householdMembers(owner.getHouseholdId()).stream()
617	            .mapToInt(this.ownerMapper::membershipLevel)
618	            .max();
619	        return maxHouseholdLevel.isPresent()
620	            ? Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1)
621	            : ownLevel;
622	    }
