652	    /**
653	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
654	     * is none. The create has already cleared the hard-duplicate identity check
655	     * ({@link #rejectDuplicateIdentity}), so its {@code identityKey} matches no existing owner; it is a
656	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code postcode} and
657	     * the {@linkplain Soundex#soundex Soundex} of its {@code lastName} while their identity keys still
658	     * differ. Because the telephone is part of the identity key, two owners with the same last name and
659	     * postcode but different telephones have differing keys and so soft-match here rather than colliding
660	     * as a hard duplicate. The oldest such owner (the earliest persisted) is returned so the flag points
661	     * at the original record; owners with no postcode never match, since a shared postcode is required.
662	     *
663	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
664	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
665	     *         duplicate
666	     */
667	    private Integer findPossibleDuplicate(Owner owner) {
668	        String postcode = owner.getPostcode();
669	        if (postcode == null) {
670	            return null;
671	        }
672	        String identityKey = OwnerIdentity.identityKey(owner);
673	        String lastNameCode = Soundex.soundex(owner.getLastName());
674	        return activeOwners().stream()
675	            .filter(existing -> !identityKey.equals(OwnerIdentity.identityKey(existing)))
676	            .filter(existing -> lastNameCode.equals(Soundex.soundex(existing.getLastName())))
677	            .filter(existing -> postcode.equals(existing.getPostcode()))
678	            .map(Owner::getId)
679	            .filter(Objects::nonNull)
680	            .min(Integer::compareTo)
681	            .orElse(null);
682	    }
