684	    /**
685	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
686	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
687	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
688	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
689	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
690	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
691	     * duplicate, so it is never flagged.
692	     *
693	     * @param owner           the owner being created, with telephone already normalized and
694	     *                        lastName/postcode set
695	     * @param sharesHousehold whether the request opted in to sharing a household
696	     */
697	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
698	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
699	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
700	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
701	    }
