772	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
773	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
774	     * Too Many Requests}.
775	     *
776	     * @param registrationDate   the create's effective registration date, already rolled onto a
777	     *                           business day by {@link #effectiveRegistrationDate}
778	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
779	     *                           {@code registrationDate} equals {@code registrationDate}
780	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
781	     *                                              owner registrations
782	     */
783	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
784	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
785	            throw new OwnerDailyRegistrationLimitException(registrationDate);
786	        }
787	    }
788	
789	    /**
790	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
791	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
792	     * bulk-signup warning are judged on.
793	     *
794	     * @param registrationDate the create's effective registration date, already rolled onto a business
795	     *                         day by {@link #effectiveRegistrationDate}
796	     * @return the number of existing owners registered on that day
797	     */
798	    private long countRegisteredOn(LocalDate registrationDate) {
799	        return this.clinicService.findAllOwners().stream()
800	            .map(Owner::getRegistrationDate)
801	            .filter(registrationDate::equals)
802	            .count();
803	    }
804	}
