        ownerDto.getMembershipLevel());
    OwnerCreatedEvent event = new OwnerCreatedEvent(EVENT_SEQ.incrementAndGet(),
        owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
    AUDIT.info(event.toJson());
}

